package org.apache.commons.math.stat.inference;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math.MathException;
import org.apache.commons.math.distribution.ChiSquaredDistribution;
import org.apache.commons.math.distribution.ChiSquaredDistributionImpl;
import org.apache.commons.math.distribution.DistributionFactory;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class ChiSquareTestImpl_chiSquare_TriageGen1Test {

    private ChiSquareTestImpl chiSquareTestImpl;
    private static final double DELTA = 1e-10;

    @Before
    public void setUp() {
        chiSquareTestImpl = new ChiSquareTestImpl();
    }

    @Test
    public void testChiSquare_Success() {
        double[] expected = {10.0, 20.0, 30.0};
        long[] observed = {12L, 18L, 30L};
        // Calculation:
        // (12-10)^2 / 10 = 4 / 10 = 0.4
        // (18-20)^2 / 20 = 4 / 20 = 0.2
        // (30-30)^2 / 30 = 0 / 30 = 0.0
        // Sum = 0.6
        double expectedResult = 0.6;
        assertEquals(expectedResult, chiSquareTestImpl.chiSquare(expected, observed), DELTA);
    }














}

