import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class ChiSquareTestImpl_chiSquare_TriageGen1Test {

    private ChiSquareTestImpl chiSquareTestImpl;
    private static final double DELTA = 1e-10;

    @Before
    public void setUp() {
        chiSquareTestImpl = new ChiSquareTestImpl();
    }















    @Test
    public void testChiSquare_LargeValues() {
        double[] expected = {1000000.0, 2000000.0};
        long[] observed = {1000001L, 1999999L};
        // (1)^2 / 1,000,000 + (-1)^2 / 2,000,000
        // 1e-6 + 0.5e-6 = 1.5e-6
        double expectedResult = 0.0000015;
        assertEquals(expectedResult, chiSquareTestImpl.chiSquare(expected, observed), 1e-12);
    }
}
